    x_denominator:"I"$x_denominator;
    y_numerator:"I"$y_numerator;
    y_denominator:"I"$y_denominator;

    / Multiply the numerators and denominators
    result_numerator:x_numerator*y_numerator;
    result_denominator:x_denominator*y_denominator;

    / Check if the result is a whole number
    result_numerator mod result_denominator=0
    }
```

